import{_ as o,o as d,c as t,ag as a}from"./chunks/framework.BaNuf0sO.js";const g=JSON.parse('{"title":"ModalImagePreview（图片预览弹窗·命令式入口）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/modal/docs/README-ModalImagePreview.md","filePath":"docs/core/src/components/modal/docs/README-ModalImagePreview.md"}'),s={name:"docs/core/src/components/modal/docs/README-ModalImagePreview.md"};function l(i,e,c,r,n,h){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="modalimagepreview-图片预览弹窗·命令式入口" tabindex="-1">ModalImagePreview（图片预览弹窗·命令式入口） <a class="header-anchor" href="#modalimagepreview-图片预览弹窗·命令式入口" aria-label="Permalink to &quot;ModalImagePreview（图片预览弹窗·命令式入口）&quot;">​</a></h1><blockquote><p>图片预览原语：<strong>ElImageViewer 薄层适配</strong>（el 图片预览组件本体 = 全屏 lightbox）+ <strong>弹窗配置化契约包装</strong>（<code>v-model:show</code> / 注册形态注入 / 双输入源）。 注册 key 建议 <code>modalImagePreview</code>（ModalShelf/Porter 注册项）；全局预置 key = <code>APP_GLOBAL_IMAGE_PREVIEW_KEY</code>。 范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：<strong>命令式 / 配置化唤起图片预览</strong>——业务按钮、编排逻辑、全局遥控器 <code>evoke</code> 开图（el 图片预览无命令式 API，本组件是唯一桥梁）</li><li><strong>何时不用</strong>：<strong>点击图片看大图 → 直接用 <code>ElImage</code> 的 <code>preview-src-list</code></strong>（el 原生放大查看器，零开发）；触发组件 <code>ImagePreviewTrigger</code> 点击即直达 ElImage 预览，<strong>不经本组件</strong>——本组件只服务「不经过点击」的命令式入口</li><li><strong>为什么是薄适配</strong>：el 图片预览组件（<code>ElImageViewer</code>）本身就是全屏 lightbox 弹层（遮罩 + 缩放旋转 + ESC/遮罩关闭）——<strong>直接以它为底座</strong>，只补一层弹窗配置化契约；[MUST NOT] 再包 <code>ModalConfirm</code>（两层嵌套：弹窗内再点才放大——脱裤子放屁，已废弃）</li><li>关键机制：<code>defineModel(&quot;show&quot;)</code> → 内部映射 ElImageViewer <code>v-model:visible</code>；关闭（ESC / 遮罩 / 关闭按钮）→ <code>update:visible</code> → 映射 <code>update:show</code> → 架子 <code>@update:show</code> 收尾关闭</li><li><strong>注册形态（ModalShelf/Porter）</strong>：架子渲染只传 <code>show</code>/<code>payload</code>/<code>closeFn</code>/<code>removeFn</code>——业务值走 payload，双输入源：<code>src</code> = <code>props.src ?? payload.src</code>（原语用法 prop 直传、注册用法 payload 承载）</li><li><strong>全局预置</strong>：core 预置 <code>APP_GLOBAL_IMAGE_PREVIEW_KEY</code>——AppLayout <code>enableGlobalImagePreview</code> 开启后自动注册进全局弹窗（见 README-AppLayout）；命令式 <code>globalModalRemote.evoke(APP_GLOBAL_IMAGE_PREVIEW_KEY, { src })</code> 即开图</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ModalImagePreview</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/a.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>show</code> 必传（<code>v-model:show</code>）；<code>src</code> 必传（图片地址）</li><li>打开即全屏 lightbox（el 原生：缩放 / 旋转 / 左右切换 / ESC / 遮罩关闭）</li><li>命令式：<code>globalModalRemote.evoke(APP_GLOBAL_IMAGE_PREVIEW_KEY, { src })</code></li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：<code>show</code> + <code>src</code> = 全屏图片预览</strong>——绝大多数命令式场景只传这两项。</li><li><code>url-list</code> / <code>initial-index</code>：多图切换（<code>$attrs</code> 透传 ElImageViewer）。</li><li><code>hide-on-click-modal</code> / <code>close-on-press-escape</code> / <code>show-close</code>：关闭通道控制（透传 ElImageViewer）。</li><li>点图放大的「点击路径」不归本组件：<code>ImagePreviewTrigger</code> / 任意 <code>ElImage</code> 的 <code>preview-src-list</code> 直达。</li><li><strong>完整能力演示</strong>：<code>apps/reference/src/pages/modal/preview/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-内联-defineprops-无-types-ts" tabindex="-1">Props（内联 defineProps，无 types.ts） <a class="header-anchor" href="#props-内联-defineprops-无-types-ts" aria-label="Permalink to &quot;Props（内联 defineProps，无 types.ts）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>boolean</code>（必传）</td><td>—</td><td>可见性（v-model:show → ElImageViewer visible）</td></tr><tr><td><code>src</code></td><td><code>string</code>（必传）</td><td>—</td><td>图片地址（双输入源 <code>props.src ?? payload.src</code>）</td></tr><tr><td><code>payload</code></td><td><code>{ src?: string }</code></td><td>—</td><td>注册形态注入（架子渲染只传 payload；原语用法无需传）</td></tr><tr><td><code>closeFn</code> / <code>removeFn</code></td><td><code>() =&gt; void</code></td><td>—</td><td>注册形态注入的关闭/移除出口（声明避免泄漏进 <code>$attrs</code>）</td></tr><tr><td><code>onClose</code></td><td><code>(status?: boolean) =&gt; void</code></td><td>—</td><td>关闭回调（ElImageViewer @close 触发）</td></tr></tbody></table><blockquote><p><strong>ElImageViewer 属性全量透传</strong>：<code>$attrs</code> 直达——<code>url-list</code> / <code>initial-index</code> / <code>hide-on-click-modal</code> / <code>close-on-press-escape</code> / <code>show-close</code> / <code>teleported</code> / <code>z-index</code> 等均可用。</p></blockquote><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>update:show</code></td><td><code>boolean</code></td><td>可见性同步（v-model；ElImageViewer 关闭 → <code>update:visible</code> 映射）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无（ElImageViewer 为全屏查看器，无内容插槽语义）</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>[MUST NOT] 包 <code>ModalConfirm</code> 底座</strong>：两层预览嵌套已废弃（弹窗内再点放大 = 脱裤子放屁）——本组件 = ElImageViewer + 契约，薄层不叠加</li><li><strong>点击路径不走本组件</strong>：点图看大图用 <code>ElImage</code> <code>preview-src-list</code> / <code>ImagePreviewTrigger</code> 直达——本组件只服务命令式入口，两路径各司其职</li><li><strong>无标题 / 无按钮语义</strong>：lightbox 沉浸形态不配 title/footer/确认取消——需要「弹窗 + 图片 + 操作按钮」的形态用 <code>ModalConfirm</code> + <code>ElImage</code> 消费方自拼</li><li><strong>关闭映射链</strong>：ElImageViewer 关闭 → <code>update:visible</code> → <code>update:show</code> → 架子收尾——[MUST NOT] 另接关闭逻辑造成双通道</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>弹层族：<code>ModalConfirm</code>（确认/表单弹窗体系——图片预览不再用它做底座）、<code>ModalForm</code>、<code>ModalDetail</code></li><li>预览族：<code>ModalVideoPreview</code>（视频预览，同为 lightbox 形态；视频无 el 原生组件，ElDialog 直配黑底）</li><li>触发端：<code>ImagePreviewTrigger</code>（ElImage + 懒加载 + 占位兜底，<strong>点击直达 ElImage 原生预览</strong>，不经本组件）</li><li>命令式弹窗体系：<code>ModalShelf</code>（架子 + level 层级）+ <code>ModalPorter</code>（modalList 注册表）+ 全局遥控器（<code>globalModalRemote.evoke(APP_GLOBAL_IMAGE_PREVIEW_KEY, { src })</code>）</li><li>范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></li></ul>',25)])])}const m=o(s,[["render",l]]);export{g as __pageData,m as default};
